// GUI catalog generator (brick G4). Reads locales/src/<lang>.json (one per locale, the extension
// messages.json shape { key: { message } }) and emits ../catalogs.js for the full 30-locale set. en is the
// source of truth and the per-key runtime fallback: any locale missing a key is filled from en (and warned).
// Also checks that $1/$2 substitution tokens survive translation and that no message is empty. Re-run with
//   node locales/gen.js
// after editing any src JSON. Machine-drafted translations; corrections land via PR (see TRANSLATIONS.md).
const fs = require("fs"), path = require("path");
const SRC = path.join(__dirname, "src");
const LANGS = ["en", "es", "fr", "de", "it", "pt_BR", "nl", "pl", "ru", "uk", "tr", "cs", "ro", "hu",
  "el", "sv", "da", "fi", "no", "ar", "he", "fa", "hi", "th", "vi", "id", "ja", "ko", "zh_CN", "zh_TW"];

const en = JSON.parse(fs.readFileSync(path.join(SRC, "en.json"), "utf8"));
const enKeys = Object.keys(en);
const warnings = [];
const cat = {};

for (const l of LANGS) {
  const f = path.join(SRC, l + ".json");
  let d = {};
  if (fs.existsSync(f)) {
    try { d = JSON.parse(fs.readFileSync(f, "utf8")); }
    catch (e) { warnings.push(l + ": JSON PARSE ERROR " + e.message); }
  } else if (l !== "en") {
    warnings.push(l + ": MISSING FILE (all keys filled from en)");
  }
  const out = {};
  for (const k of enKeys) {
    let msg = d[k] && typeof d[k].message === "string" ? d[k].message : null;
    if (msg === null) {
      if (l !== "en") warnings.push(l + ": missing key '" + k + "' (filled from en)");
      msg = en[k].message;
    }
    ["$1", "$2"].forEach(tok => {
      if (en[k].message.indexOf(tok) >= 0 && msg.indexOf(tok) < 0) warnings.push(l + ": key '" + k + "' dropped " + tok);
    });
    if (msg === "") warnings.push(l + ": key '" + k + "' is EMPTY");
    out[k] = { message: msg };
  }
  for (const k of Object.keys(d)) if (!en[k]) warnings.push(l + ": extra key '" + k + "' (ignored)");
  cat[l] = out;
}

let body = "// GENERATED by locales/gen.js from locales/src/<lang>.json. Do NOT hand-edit; edit the src JSON\n";
body += "// and re-run `node locales/gen.js`. en is the source of truth and the per-key runtime fallback.\n";
body += "// 30 locales, machine-drafted; corrections welcome via PR (see locales/TRANSLATIONS.md).\n";
body += "window.I18N = " + JSON.stringify(cat, null, 2) + ";\n";
// index.html loads <script src="locales/catalogs.js">, i.e. app/dist/locales/catalogs.js == this dir.
fs.writeFileSync(path.join(__dirname, "catalogs.js"), body);

console.log("emitted catalogs.js: " + LANGS.length + " locales x " + enKeys.length + " keys");
if (warnings.length) {
  console.log("\nWARNINGS (" + warnings.length + "):");
  warnings.slice(0, 80).forEach(w => console.log("  " + w));
  if (warnings.length > 80) console.log("  ...+" + (warnings.length - 80) + " more");
  process.exitCode = 1;
} else {
  console.log("no warnings: every locale has all " + enKeys.length + " keys, tokens preserved, none empty");
}
